-- 1KYCore: reviewed Sylvania content, upstream a6145c22e9ad6ac69690d4a2f7794bae4e1caf95.
-- Apply through the normal world updater. No bot/mercenary tables or data.
-- Fail before content changes if a reserved spawn GUID belongs to another entry.
-- The duplicate-key error names the guard table; resolve GUID ownership before retrying.
DROP TEMPORARY TABLE IF EXISTS `_1kycore_spawn_guard`;
CREATE TEMPORARY TABLE `_1kycore_spawn_guard` (`ok` INT PRIMARY KEY);
DROP TEMPORARY TABLE IF EXISTS `_1kycore_creature_identity`;
CREATE TEMPORARY TABLE `_1kycore_creature_identity` (`guid` BIGINT UNSIGNED PRIMARY KEY, `id` INT UNSIGNED);
DROP TEMPORARY TABLE IF EXISTS `_1kycore_gameobject_identity`;
CREATE TEMPORARY TABLE `_1kycore_gameobject_identity` (`guid` BIGINT UNSIGNED PRIMARY KEY, `id` INT UNSIGNED);

