DELETE c FROM creature c JOIN `_1kycore_creature_identity` e ON c.guid=e.guid AND c.id=e.id WHERE c.guid IN (290306567,290308062) AND c.id>=400000;
DELETE g FROM gameobject g JOIN `_1kycore_gameobject_identity` e ON g.guid=e.guid AND g.id=e.id LEFT JOIN gameobject_template t ON t.entry=g.id WHERE t.entry IS NULL;
-- Remove obsolete bridge spawns only when both GUID and old template match.
DELETE FROM gameobject WHERE guid BETWEEN 210300200 AND 210300220 AND id IN (1000200,1000201,1000202);
DROP TEMPORARY TABLE `_1kycore_creature_identity`, `_1kycore_gameobject_identity`, `_1kycore_spawn_guard`;
