INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107683,0,0,'Fools. Your pathetic souls will fuel the Legion\'s coming!',12,0,100.0,0,0,0,0,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107683,1,0,'Stand down, $r scum. You know not the forces you tempt.',12,0,100.0,0,0,0,0,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107683,1,1,'Can you not feel it? The warm embrace of the Legion comes, you need only welcome it!',12,0,100.0,0,0,0,112652,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107683,1,2,'You are not worth saving. Die, miserable worm!',12,0,100.0,0,0,0,112653,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107683,4,0,'You are too late. We are... everywhere...',12,0,100.0,0,0,0,112654,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107736,0,0,'Yes, yes! They grow closer with each moment!',12,0,100.0,0,0,0,0,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107736,1,0,'You will not interrupt my work. The Legion will have this world!',12,0,100.0,0,0,0,112590,0,'LegionCore')
