INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (105724,0,0,'Ye made it! This land haunts me still... so much pain and death. Well, let\'s get on with it.',12,0,100.0,0,0,0,108611,0,'LegionCore')
