INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (105910,0,0,'Cato! I\'m glad ye could make it. The shield is close... I can feel it!',12,0,100.0,0,0,0,108846,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (105910,1,0,'Cato\'s the best healer around. We\'re lucky we didn\'t have to wait in a queue for his services!',12,0,100.0,0,0,0,108850,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (105910,2,0,'Tomb\'s up ahead. Let\'s get in there and find that shrine! We\'ll follow yer lead, $n.',12,0,100.0,0,0,0,114138,0,'LegionCore')
