INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107289,1,0,'There! A bit of magic to help you follow in Galford\'s footsteps. Good luck!',12,0,100.0,0,0,0,113741,0,'LegionCore')
