INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106720,0,0,'I can feel their curse weakening! You must stop them from interfering with the rite!',12,0,100.0,0,0,70424,113579,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106720,1,0,'It is done! You rotten Bonespeaker dogs cannot deny my place in the Halls of Valor any longer!',14,0,100.0,0,0,70425,113580,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106752,1,0,'Don\'t mess with the mountain!',12,0,100.0,0,0,57966,107085,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107984,3,0,'Not wise to question Odyn. He says you lead then you lead!',12,0,100.0,66,0,69369,120496,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107985,3,0,'Our enemies will tremble!',12,0,100.0,15,0,69561,120479,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107986,3,0,'To live again and to fight! The glory of battle awaits!',12,0,100.0,1,0,69370,120498,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107987,0,0,'Armies of Ulduar, heed Odyn\'s call!',14,0,100.0,22,0,68390,119679,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108961,3,0,'Excellent, commander. Danath awaits you on Krasus\' Landing.',12,0,100.0,1,0,63537,114680,0,'LegionCore')
