INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102244,0,0,'Invaders! Crush them!',14,0,100.0,0,0,0,104677,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (102244,0,1,'You belong... to the Inquisition!',12,0,100.0,0,0,0,103542,0,'LegionCore')
