INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (103148,5,0,'Come, children, we must get to the temple. $n, I\'ll need your help. The complex is crawling with evil!',12,0,100.0,0,0,0,100187,0,'LegionCore')
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (103148,6,0,'Infernal incoming! Watch your head!',14,0,100.0,0,0,0,100352,0,'LegionCore')
